                              <Button 
                                variant="ghost" 
                                className="w-full group/btn justify-between hover:bg-navy/5"
                                data-testid={`button-blog-read-${post.id}`}
                              >
                                Read More
                                <motion.div
                                  animate={{ x: [0, 5, 0] }}
                                  transition={{ duration: 1.5, repeat: Infinity }}
                                >
                                  <ArrowRight className="h-4 w-4" />
                                </motion.div>
                              </Button>
                            </Link>
                          </motion.div>
                        </div>
                      </Card>
                    </motion.div>
                  </StaggerItem>
                ))}
          </StaggerContainer>
        </div>
      </section>
    </div>
  );
}

