    return newJudge;
  }

  async deleteJudge(id: string): Promise<boolean> {
    return this.judges.delete(id);
  }

  async getGalleryImages(): Promise<GalleryImage[]> {
    return Array.from(this.galleryImages.values()).sort((a, b) => a.order - b.order);
