      (a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime()
    );
  }

  async createNews(news: InsertNews): Promise<News> {
    const id = randomUUID();
    const newsItem: News = {
      id,
      ...news,
      publishedAt: new Date(),
      createdAt: new Date(),
    };
    this.news.set(id, newsItem);
    return newsItem;
  }

  async deleteNews(id: string): Promise<boolean> {
    return this.news.delete(id);
  }

  async getNotices(): Promise<Notice[]> {
    return Array.from(this.notices.values()).sort(
      (a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime()
    );
  }

  async createNotice(notice: InsertNotice): Promise<Notice> {
    const id = randomUUID();
    const newNotice: Notice = {
      id,
      ...notice,
      publishedAt: new Date(),
      createdAt: new Date(),
    };
    this.notices.set(id, newNotice);
    return newNotice;
  }

  async updateNotice(id: string, updates: Partial<Notice>): Promise<Notice | undefined> {
    const notice = this.notices.get(id);
    if (!notice) return undefined;

    const updated = { ...notice, ...updates };
    this.notices.set(id, updated);
    return updated;
  }

  async deleteNotice(id: string): Promise<boolean> {
    return this.notices.delete(id);
  }

  async getVideos(): Promise<Video[]> {
    return Array.from(this.videos.values()).sort((a, b) => a.order - b.order);
  }

  async createVideo(video: InsertVideo): Promise<Video> {
    const id = randomUUID();
    const newVideo: Video = { id, ...video, createdAt: new Date() };
    this.videos.set(id, newVideo);
    return newVideo;
  }

  async deleteVideo(id: string): Promise<boolean> {
    return this.videos.delete(id);
  }

  async getContactMessages(): Promise<ContactMessage[]> {
    return Array.from(this.contactMessages.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  async createContactMessage(message: InsertContactMessage): Promise<ContactMessage> {
    const id = randomUUID();
    const contactMessage: ContactMessage = {
      id,
      ...message,
      isRead: false,
      status: "new",
      priority: "medium",
      tags: null,
      notes: null,
      assignedTo: null,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    this.contactMessages.set(id, contactMessage);
    return contactMessage;
  }

  async markMessageAsRead(id: string): Promise<ContactMessage | undefined> {
    const message = this.contactMessages.get(id);
    if (!message) return undefined;

    message.isRead = true;
    this.contactMessages.set(id, message);
    return message;
  }

  async updateContactMessage(id: string, data: Partial<ContactMessage>): Promise<ContactMessage | undefined> {
    const message = this.contactMessages.get(id);
    if (!message) return undefined;

    const updatedMessage = { ...message, ...data, updatedAt: new Date() };
    this.contactMessages.set(id, updatedMessage);
    return updatedMessage;
  }

  async getFooterContent(): Promise<FooterContent | undefined> {
    return this.footerContent;
  }

  async updateFooterContent(content: InsertFooterContent): Promise<FooterContent> {
    this.footerContent = {
      id: this.footerContent?.id || randomUUID(),
      ...content,
      updatedAt: new Date(),
    };
    return this.footerContent;
  }

  private siteSettings: SiteSettings | undefined;

  async getSiteSettings(): Promise<SiteSettings | undefined> {
    return this.siteSettings;
  }

  async updateSiteSettings(settings: InsertSiteSettings): Promise<SiteSettings> {
    this.siteSettings = {
      id: this.siteSettings?.id || randomUUID(),
      ...settings,
      updatedAt: new Date(),
    };
    return this.siteSettings;
  }
}

import { DbStorage } from "./db-storage";

export const storage = new DbStorage();

