  atom: { bg: "from-blue-500/20 to-blue-600/10", text: "text-blue-600", glow: "group-hover:shadow-blue-500/20" },
  flask: { bg: "from-purple-500/20 to-purple-600/10", text: "text-purple-600", glow: "group-hover:shadow-purple-500/20" },
  leaf: { bg: "from-green-500/20 to-green-600/10", text: "text-green-600", glow: "group-hover:shadow-green-500/20" },
  code: { bg: "from-orange-500/20 to-orange-600/10", text: "text-orange-600", glow: "group-hover:shadow-orange-500/20" },
  bot: { bg: "from-cyan-500/20 to-cyan-600/10", text: "text-cyan-600", glow: "group-hover:shadow-cyan-500/20" },
  recycle: { bg: "from-emerald-500/20 to-emerald-600/10", text: "text-emerald-600", glow: "group-hover:shadow-emerald-500/20" },
};

export default function Categories() {
  const { data: categories, isLoading } = useQuery<Category[]>({
    queryKey: ["/api/categories"],
  });

  return (
    <div className="min-h-screen pt-20">
      <section className="relative py-24 bg-gradient-to-b from-cream-200 via-cream-300 to-cream-400 overflow-hidden">
        <HeroBackground />
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, ease: [0.25, 0.1, 0.25, 1] }}
            className="text-center"
          >
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ delay: 0.2, type: "spring", stiffness: 200 }}
              className="relative mb-8"
            >
              <motion.img 
                src="/assets/logo.png" 
                alt="NSN Logo" 
                className="h-24 w-24 mx-auto drop-shadow-2xl"
                animate={{ y: [0, -8, 0] }}
                transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
              />
              <motion.div
                className="absolute inset-0 bg-gradient-radial from-navy/10 to-transparent rounded-full blur-2xl"
                animate={{ scale: [1, 1.2, 1], opacity: [0.3, 0.5, 0.3] }}
                transition={{ duration: 3, repeat: Infinity }}
              />
            </motion.div>
            <motion.span 
              className="inline-block px-4 py-1.5 bg-navy/10 rounded-full text-navy text-sm font-medium mb-6"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.3 }}
            >
              Explore Fields
            </motion.span>
            <h1 className="text-4xl md:text-5xl lg:text-6xl font-heading font-bold text-navy mb-6">
              Science Categories
            </h1>
            <p className="text-xl text-navy/70 max-w-3xl mx-auto">
              Explore diverse fields of scientific innovation and discovery
            </p>
          </motion.div>
        </div>
      </section>

      <section className="py-24 bg-background relative overflow-hidden">
        <GridPattern className="opacity-30" />
        <GradientOrb className="w-[400px] h-[400px] -top-32 -left-32" color="navy" />
        <GradientOrb className="w-[300px] h-[300px] bottom-0 right-0" color="solar" />

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <StaggerContainer className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {isLoading
              ? [...Array(6)].map((_, i) => (
                  <Card key={i} className="p-10">
                    <Skeleton className="h-20 w-20 mx-auto mb-8 rounded-2xl" />
                    <Skeleton className="h-8 w-3/4 mx-auto mb-4" />
                    <Skeleton className="h-24 w-full" />
                  </Card>
                ))
              : categories?.map((category, index) => {
                  const IconComponent = iconMap[category.icon] || Atom;
                  const colors = colorMap[category.icon] || colorMap.atom;
                  return (
                    <StaggerItem key={category.id}>
                      <motion.div
                        whileHover={{ y: -12, scale: 1.02 }}
                        transition={{ type: "spring", stiffness: 300, damping: 20 }}
                      >
                        <Card
                          className={`p-10 text-center cursor-pointer border-2 border-navy/5 hover:border-navy/20 group relative overflow-hidden h-full transition-all duration-500 hover:shadow-2xl ${colors.glow}`}
                          data-testid={`card-category-${category.id}`}
                        >
                          <motion.div
                            className={`absolute inset-0 bg-gradient-to-br ${colors.bg} opacity-0 group-hover:opacity-100 transition-opacity duration-500`}
                          />

                          <motion.div
                            className={`relative inline-flex p-6 bg-gradient-to-br ${colors.bg} rounded-3xl mb-8`}
                            whileHover={{ rotate: [0, -10, 10, 0], scale: 1.1 }}
                            transition={{ duration: 0.5 }}
                          >
                            <motion.div
                              className="absolute inset-0 bg-current rounded-3xl blur-xl opacity-0 group-hover:opacity-20 transition-opacity"
                            />
                            <IconComponent className={`h-14 w-14 ${colors.text} relative`} />
                          </motion.div>

                          <h3
                            className="text-2xl font-heading font-bold mb-4 relative"
                            data-testid={`text-category-name-${category.id}`}
                          >
                            {category.name}
                          </h3>
                          <p className="text-muted-foreground leading-relaxed relative text-lg">
                            {category.description}
                          </p>

                          <motion.div 
                            className="mt-6 opacity-0 group-hover:opacity-100 transition-opacity"
                            initial={{ y: 10 }}
                            whileHover={{ y: 0 }}
                          >
                            <span className={`inline-flex items-center gap-2 ${colors.text} font-medium`}>
                              Learn more
                              <ArrowRight className="h-4 w-4" />
                            </span>
                          </motion.div>
                        </Card>
                      </motion.div>
                    </StaggerItem>
                  );
                })}
          </StaggerContainer>
        </div>
      </section>

      <section className="py-24 bg-gradient-to-b from-background to-card relative overflow-hidden">
        <ParticleField count={15} />

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <FadeIn className="text-center">
            <motion.div
              className="inline-flex p-5 bg-gradient-to-br from-solar/20 to-navy/10 rounded-3xl mb-8"
              whileHover={{ scale: 1.1, rotate: 5 }}
            >
              <Lightbulb className="h-12 w-12 text-solar-700" />
            </motion.div>
            <h2 className="text-3xl md:text-4xl font-heading font-bold mb-6">
              Don't See Your Field?
            </h2>
            <p className="text-muted-foreground max-w-2xl mx-auto mb-10 text-lg">
              We're always expanding our categories. Contact us to discuss your unique project idea and how it could fit into our science fair.
            </p>
            <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.98 }}>
              <Link href="/contact">
                <Button
                  size="lg"
                  className="bg-gradient-to-r from-navy to-navy-600 hover:from-navy-600 hover:to-navy text-cream shadow-xl shadow-navy/30 px-10 py-6 text-lg font-semibold group"
                >
                  Get in Touch
                  <motion.div
                    className="ml-2"
                    animate={{ x: [0, 5, 0] }}
                    transition={{ duration: 1.5, repeat: Infinity }}
                  >
                    <ArrowRight className="h-5 w-5" />
                  </motion.div>
                </Button>
              </Link>
            </motion.div>
          </FadeIn>
        </div>
      </section>
    </div>
  );
}

