import { motion } from "framer-motion";
import { useQuery } from "@tanstack/react-query";
import { Clock, MapPin, Calendar as CalendarIcon, Users, ArrowRight, Sparkles } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Link } from "wouter";
import type { ScheduleItem, Judge } from "@shared/schema";
import { HeroBackground, GradientOrb, GridPattern, ParticleField } from "@/components/AnimatedBackground";
import { FadeIn, StaggerContainer, StaggerItem } from "@/components/PageTransition";

export default function Schedule() {
  const { data: scheduleItems, isLoading: scheduleLoading } = useQuery<ScheduleItem[]>({
    queryKey: ["/api/schedule"],
  });

  const { data: judges, isLoading: judgesLoading } = useQuery<Judge[]>({
    queryKey: ["/api/judges"],
  });

  const groupedSchedule = scheduleItems?.reduce((acc, item) => {
    if (!acc[item.date]) {
      acc[item.date] = [];
    }
    acc[item.date].push(item);
    return acc;
  }, {} as Record<string, ScheduleItem[]>);

  return (
    <div className="min-h-screen pt-20">
      <section className="relative py-24 bg-gradient-to-b from-cream-200 via-cream-300 to-cream-400 overflow-hidden">
        <HeroBackground />
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, ease: [0.25, 0.1, 0.25, 1] }}
            className="text-center"
          >
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ delay: 0.2, type: "spring", stiffness: 200 }}
              className="relative mb-8"
            >
              <motion.img 
                src="/assets/logo.png" 
                alt="NSN Logo" 
                className="h-24 w-24 mx-auto drop-shadow-2xl"
                animate={{ y: [0, -8, 0] }}
                transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
              />
              <motion.div
                className="absolute inset-0 bg-gradient-radial from-navy/10 to-transparent rounded-full blur-2xl"
                animate={{ scale: [1, 1.2, 1], opacity: [0.3, 0.5, 0.3] }}
                transition={{ duration: 3, repeat: Infinity }}
              />
            </motion.div>
            <motion.span 
              className="inline-block px-4 py-1.5 bg-navy/10 rounded-full text-navy text-sm font-medium mb-6"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.3 }}
            >
              Event Timeline
            </motion.span>
            <h1 className="text-4xl md:text-5xl lg:text-6xl font-heading font-bold text-navy mb-6">
              Event Schedule
            </h1>
            <p className="text-xl text-navy/70 max-w-3xl mx-auto">
              Plan your science fair journey with our detailed timeline
            </p>
          </motion.div>
        </div>
      </section>

      <section className="py-24 bg-background relative overflow-hidden">
        <GridPattern className="opacity-30" />
        <GradientOrb className="w-[400px] h-[400px] -top-32 -left-32" color="navy" />

        <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          {scheduleLoading ? (
            <div className="space-y-8">
              {[...Array(4)].map((_, i) => (
                <Card key={i} className="p-8">
                  <Skeleton className="h-8 w-48 mb-6" />
                  <Skeleton className="h-32 w-full" />
                </Card>
              ))}
            </div>
          ) : groupedSchedule && Object.keys(groupedSchedule).length > 0 ? (
            <div className="space-y-16">
              {Object.entries(groupedSchedule).map(([date, items], dateIndex) => (
                <FadeIn key={date} delay={dateIndex * 0.1}>
                  <div className="flex items-center gap-4 mb-8">
                    <motion.div
                      className="p-3 bg-gradient-to-br from-navy/10 to-solar/10 rounded-xl"
                      whileHover={{ scale: 1.1, rotate: 5 }}
                    >
                      <CalendarIcon className="h-6 w-6 text-navy" />
                    </motion.div>
                    <h2 className="text-2xl font-heading font-bold">
                      {new Date(date).toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
                    </h2>
                  </div>

                  <div className="relative space-y-6 pl-10 border-l-2 border-navy/20">
                    {items.map((item, itemIndex) => (
                      <motion.div
                        key={item.id}
                        initial={{ opacity: 0, x: -30 }}
                        whileInView={{ opacity: 1, x: 0 }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.5, delay: itemIndex * 0.1 }}
                        className="relative"
                      >
                        <motion.div 
                          className="absolute -left-[45px] top-4 w-4 h-4 bg-gradient-to-br from-navy to-navy-600 rounded-full border-4 border-background shadow-lg"
                          whileHover={{ scale: 1.5 }}
                          transition={{ type: "spring", stiffness: 300 }}
                        />

                        <motion.div whileHover={{ y: -5, x: 5 }}>
                          <Card className="p-8 border-2 border-navy/5 hover:border-navy/20 hover:shadow-2xl transition-all duration-500 group relative overflow-hidden" data-testid={`card-schedule-${item.id}`}>
                            <motion.div
                              className="absolute inset-0 bg-gradient-to-br from-navy/5 to-solar/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500"
                            />

                            <div className="relative flex flex-col md:flex-row md:items-start md:justify-between gap-4 mb-4">
                              <div className="flex-1">
                                <div className="flex flex-wrap items-center gap-3 mb-4">
                                  <motion.div whileHover={{ scale: 1.1 }}>
                                    <Badge className="bg-navy/10 text-navy border-navy/20 px-3 py-1">
                                      {item.type}
                                    </Badge>
                                  </motion.div>
                                  <span className="text-sm text-muted-foreground flex items-center gap-2 bg-muted/50 px-3 py-1 rounded-full">
                                    <Clock className="h-4 w-4" />
                                    {item.startTime} - {item.endTime}
                                  </span>
                                </div>
                                <h3 className="text-xl font-heading font-bold mb-3" data-testid={`text-schedule-title-${item.id}`}>
                                  {item.title}
                                </h3>
                                <p className="text-muted-foreground mb-4 text-lg">{item.description}</p>
                                <div className="flex items-center gap-2 text-sm text-muted-foreground bg-muted/30 px-4 py-2 rounded-lg inline-flex">
                                  <MapPin className="h-4 w-4 text-navy" />
                                  <span>{item.location}</span>
                                </div>
                              </div>
                            </div>
                          </Card>
                        </motion.div>
                      </motion.div>
                    ))}
                  </div>
                </FadeIn>
              ))}
            </div>
          ) : (
            <FadeIn>
              <Card className="p-16 text-center border-2 border-dashed border-navy/20">
                <motion.div
                  animate={{ y: [0, -10, 0] }}
                  transition={{ duration: 2, repeat: Infinity }}
                >
                  <CalendarIcon className="h-20 w-20 text-muted-foreground mx-auto mb-6" />
                </motion.div>
                <p className="text-muted-foreground text-xl mb-6">Schedule will be announced soon</p>
                <Link href="/contact">
                  <Button variant="outline" className="border-navy/20">
                    Get Notified
                  </Button>
                </Link>
              </Card>
            </FadeIn>
          )}
        </div>
      </section>

      <section className="py-24 bg-gradient-to-b from-background to-card relative overflow-hidden">
        <ParticleField count={15} />
        <GradientOrb className="w-[500px] h-[500px] bottom-0 right-0" color="solar" />

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <FadeIn className="text-center mb-16">
            <motion.div
              className="inline-flex p-5 bg-gradient-to-br from-navy/10 to-solar/10 rounded-3xl mb-8"
              whileHover={{ scale: 1.1, rotate: 5 }}
            >
              <Users className="h-12 w-12 text-navy" />
            </motion.div>
            <h2 className="text-3xl md:text-4xl font-heading font-bold mb-4">Our Expert Judges</h2>
            <p className="text-muted-foreground max-w-2xl mx-auto text-lg">
              Meet the expert panel evaluating projects and guiding young scientists
            </p>
          </FadeIn>

          <StaggerContainer className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {judgesLoading
              ? [...Array(6)].map((_, i) => (
                  <Card key={i} className="p-8">
                    <Skeleton className="h-28 w-28 rounded-full mx-auto mb-6" />
                    <Skeleton className="h-6 w-3/4 mx-auto mb-2" />
                    <Skeleton className="h-4 w-1/2 mx-auto mb-4" />
                    <Skeleton className="h-20 w-full" />
                  </Card>
                ))
              : judges?.map((judge, index) => (
                  <StaggerItem key={judge.id}>
                    <motion.div
                      whileHover={{ y: -10 }}
                      transition={{ type: "spring", stiffness: 300 }}
                    >
                      <Card className="p-8 text-center h-full border-2 border-navy/5 hover:border-navy/20 hover:shadow-2xl transition-all duration-500 group relative overflow-hidden" data-testid={`card-judge-${judge.id}`}>
                        <motion.div
                          className="absolute inset-0 bg-gradient-to-br from-navy/5 to-solar/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500"
                        />

                        <motion.div
                          whileHover={{ scale: 1.1 }}
                          transition={{ type: "spring", stiffness: 300 }}
                          className="relative"
                        >
                          <motion.div 
                            className="absolute inset-0 bg-gradient-to-br from-navy/20 to-solar/20 rounded-full blur-xl opacity-0 group-hover:opacity-100 transition-opacity"
                          />
                          <Avatar className="h-28 w-28 mx-auto mb-6 border-4 border-navy/20 relative shadow-lg">
                            <AvatarImage src={judge.image || undefined} alt={judge.name} />
                            <AvatarFallback className="text-2xl font-heading bg-gradient-to-br from-navy/10 to-solar/10">
                              {judge.name.split(" ").map((n) => n[0]).join("")}
                            </AvatarFallback>
                          </Avatar>
                        </motion.div>

                        <h3 className="text-xl font-heading font-bold mb-2 relative" data-testid={`text-judge-name-${judge.id}`}>
                          {judge.name}
                        </h3>
                        <p className="text-solar-600 text-sm font-medium mb-1 relative">{judge.expertise}</p>
                        <p className="text-muted-foreground text-sm mb-4 relative">{judge.organization}</p>
                        <p className="text-muted-foreground text-sm leading-relaxed relative">
                          {judge.bio}
                        </p>
                      </Card>
                    </motion.div>
                  </StaggerItem>
                ))}
          </StaggerContainer>
        </div>
      </section>
    </div>
  );
}

