import { motion } from "framer-motion";
import { useQuery } from "@tanstack/react-query";
import { Bell, Pin, AlertCircle, Clock, Megaphone } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import type { Notice } from "@shared/schema";
import { HeroBackground, GradientOrb, GridPattern } from "@/components/AnimatedBackground";
import { FadeIn, StaggerContainer, StaggerItem } from "@/components/PageTransition";

export default function Notices() {
  const { data: notices, isLoading } = useQuery<Notice[]>({
    queryKey: ["/api/notices"],
  });

  const pinnedNotices = notices?.filter((n) => n.isPinned);
  const regularNotices = notices?.filter((n) => !n.isPinned);

  return (
    <div className="min-h-screen pt-20">
      <section className="relative py-24 bg-gradient-to-b from-cream-200 via-cream-300 to-cream-400 overflow-hidden">
        <HeroBackground />
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, ease: [0.25, 0.1, 0.25, 1] }}
            className="text-center"
          >
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ delay: 0.2, type: "spring", stiffness: 200 }}
              className="relative mb-8"
            >
              <motion.img 
                src="/assets/logo.png" 
                alt="NSN Logo" 
                className="h-24 w-24 mx-auto drop-shadow-2xl"
                animate={{ y: [0, -8, 0] }}
                transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
              />
              <motion.div
                className="absolute inset-0 bg-gradient-radial from-navy/10 to-transparent rounded-full blur-2xl"
                animate={{ scale: [1, 1.2, 1], opacity: [0.3, 0.5, 0.3] }}
                transition={{ duration: 3, repeat: Infinity }}
              />
            </motion.div>
            <motion.span 
              className="inline-block px-4 py-1.5 bg-navy/10 rounded-full text-navy text-sm font-medium mb-6"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.3 }}
            >
              Stay Updated
            </motion.span>
            <h1 className="text-4xl md:text-5xl lg:text-6xl font-heading font-bold text-navy mb-6">
              Announcements
            </h1>
            <p className="text-xl text-navy/70 max-w-3xl mx-auto">
              Important updates and notices for participants
            </p>
          </motion.div>
        </div>
      </section>

      {pinnedNotices && pinnedNotices.length > 0 && (
        <section className="py-16 bg-gradient-to-b from-solar/10 to-background border-b border-solar/20 relative overflow-hidden">
          <GradientOrb className="w-[300px] h-[300px] -top-32 -right-32" color="solar" />

          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
            <FadeIn>
              <div className="flex items-center gap-3 mb-8">
                <motion.div
                  className="p-2 bg-solar/20 rounded-lg"
                  animate={{ rotate: [0, 10, -10, 0] }}
                  transition={{ duration: 2, repeat: Infinity }}
                >
                  <Pin className="h-5 w-5 text-solar-700" />
                </motion.div>
                <h2 className="text-2xl font-heading font-bold">Pinned Notices</h2>
              </div>
            </FadeIn>

            <StaggerContainer className="space-y-6">
              {pinnedNotices.map((notice, index) => (
                <StaggerItem key={notice.id}>
                  <motion.div
                    whileHover={{ y: -5, x: 5 }}
                    transition={{ type: "spring", stiffness: 300 }}
                  >
                    <Card
                      className={`p-8 border-2 transition-all duration-500 hover:shadow-2xl group relative overflow-hidden ${
                        notice.isUrgent
                          ? "border-red-400 bg-red-50/50"
                          : "border-solar/30 bg-solar/5 hover:border-solar/50"
                      }`}
                      data-testid={`card-notice-pinned-${notice.id}`}
                    >
                      <motion.div
                        className="absolute inset-0 bg-gradient-to-br from-solar/10 to-navy/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500"
                      />

                      <div className="relative flex items-start gap-5">
                        {notice.isUrgent && (
                          <motion.div
                            animate={{ scale: [1, 1.2, 1] }}
                            transition={{ duration: 1.5, repeat: Infinity }}
                            className="p-3 bg-red-100 rounded-xl"
                          >
                            <AlertCircle className="h-6 w-6 text-red-600 flex-shrink-0" />
                          </motion.div>
                        )}
                        <div className="flex-1">
                          <div className="flex flex-wrap items-center gap-3 mb-4">
                            <motion.div whileHover={{ scale: 1.05 }}>
                              <Badge className="bg-solar/30 text-solar-800 border-solar/50 px-3 py-1">
                                <Pin className="h-3 w-3 mr-1.5" />
                                Pinned
                              </Badge>
                            </motion.div>
                            {notice.isUrgent && (
