                        />

                        <div className="relative">
                          {notice.isUrgent && (
                            <motion.div whileHover={{ scale: 1.05 }} className="mb-4">
                              <Badge className="bg-red-500 text-white px-3 py-1">
                                <AlertCircle className="h-3 w-3 mr-1.5" />
                                Urgent
                              </Badge>
                            </motion.div>
                          )}
                          <h3 className="text-xl font-heading font-bold mb-4" data-testid={`text-notice-title-${notice.id}`}>
                            {notice.title}
                          </h3>
                          <p className="text-foreground leading-relaxed whitespace-pre-wrap mb-5 text-lg">
                            {notice.content}
                          </p>
                          <div className="flex items-center gap-2 text-sm text-muted-foreground bg-muted/50 px-4 py-2 rounded-lg inline-flex">
                            <Clock className="h-4 w-4" />
                            Posted on {new Date(notice.publishedAt).toLocaleDateString()}
                          </div>
                        </div>
                      </Card>
                    </motion.div>
                  </StaggerItem>
                ))}
          </StaggerContainer>
        </div>
      </section>
    </div>
  );
}

