import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useQuery } from "@tanstack/react-query";
import { X, ZoomIn, Play, Image, Video, Camera } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import type { GalleryImage, Video as VideoType } from "@shared/schema";
import { HeroBackground, GradientOrb, GridPattern } from "@/components/AnimatedBackground";
import { FadeIn, StaggerContainer, StaggerItem } from "@/components/PageTransition";

function extractYouTubeId(url: string): string | null {
  const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
  const match = url.match(regExp);
  return match && match[2].length === 11 ? match[2] : null;
}

export default function Gallery() {
  const { data: images, isLoading: imagesLoading } = useQuery<GalleryImage[]>({
    queryKey: ["/api/gallery"],
  });

  const { data: videos, isLoading: videosLoading } = useQuery<VideoType[]>({
    queryKey: ["/api/videos"],
  });

  const [selectedImage, setSelectedImage] = useState<GalleryImage | null>(null);
  const [filter, setFilter] = useState<string>("all");
  const [activeTab, setActiveTab] = useState<string>("photos");

  const categories = ["all", ...(images?.map(img => img.category).filter((v, i, a) => v && a.indexOf(v) === i) || [])];
  const filteredImages = filter === "all" ? images : images?.filter(img => img.category === filter);

  return (
    <div className="min-h-screen pt-20">
      <section className="relative py-24 bg-gradient-to-b from-cream-200 via-cream-300 to-cream-400 overflow-hidden">
        <HeroBackground />
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, ease: [0.25, 0.1, 0.25, 1] }}
            className="text-center"
          >
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ delay: 0.2, type: "spring", stiffness: 200 }}
              className="relative mb-8"
            >
              <motion.img 
                src="/assets/logo.png" 
                alt="NSN Logo" 
                className="h-24 w-24 mx-auto drop-shadow-2xl"
                animate={{ y: [0, -8, 0] }}
                transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
              />
              <motion.div
                className="absolute inset-0 bg-gradient-radial from-navy/10 to-transparent rounded-full blur-2xl"
                animate={{ scale: [1, 1.2, 1], opacity: [0.3, 0.5, 0.3] }}
                transition={{ duration: 3, repeat: Infinity }}
              />
            </motion.div>
            <motion.span 
              className="inline-block px-4 py-1.5 bg-navy/10 rounded-full text-navy text-sm font-medium mb-6"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.3 }}
            >
              Media Collection
            </motion.span>
            <h1 className="text-4xl md:text-5xl lg:text-6xl font-heading font-bold text-navy mb-6">
              Media Gallery
            </h1>
            <p className="text-xl text-navy/70 max-w-3xl mx-auto">
              Photos and videos from our science fair events
            </p>
          </motion.div>
        </div>
      </section>

      <section className="py-12 bg-background border-b relative overflow-hidden">
        <GridPattern className="opacity-20" />

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2 }}
            >
              <TabsList className="grid w-full max-w-md grid-cols-2 mx-auto p-1 bg-navy/5 rounded-xl">
                <TabsTrigger 
                  value="photos" 
                  className="data-[state=active]:bg-navy data-[state=active]:text-cream rounded-lg transition-all flex items-center gap-2"
                >
                  <Image className="h-4 w-4" />
                  Photos
                </TabsTrigger>
                <TabsTrigger 
                  value="videos"
                  className="data-[state=active]:bg-navy data-[state=active]:text-cream rounded-lg transition-all flex items-center gap-2"
                >
                  <Video className="h-4 w-4" />
                  Videos
                </TabsTrigger>
              </TabsList>
            </motion.div>

            <TabsContent value="photos" className="mt-12">
              <motion.div 
                className="flex flex-wrap justify-center gap-3 mb-12"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.3 }}
              >
                {categories.map((category, index) => (
                  <motion.div 
                    key={category} 
                    whileHover={{ scale: 1.05, y: -2 }} 
                    whileTap={{ scale: 0.95 }}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.05 }}
                  >
                    <Button
                      variant={filter === category ? "default" : "outline"}
                      onClick={() => setFilter(category)}
                      className={`rounded-full px-6 transition-all ${
                        filter === category 
                          ? "bg-navy hover:bg-navy-600 text-cream shadow-lg shadow-navy/20" 
                          : "border-navy/20 hover:border-navy/40"
                      }`}
                      data-testid={`button-filter-${category}`}
                    >
                      {category.charAt(0).toUpperCase() + category.slice(1)}
                    </Button>
                  </motion.div>
                ))}
              </motion.div>

              <div className="columns-1 md:columns-2 lg:columns-3 gap-6 space-y-6">
                {imagesLoading
                  ? [...Array(12)].map((_, i) => (
                      <Skeleton key={i} className="h-64 w-full rounded-xl" />
                    ))
                  : filteredImages?.map((image, index) => (
                      <motion.div
                        key={image.id}
                        initial={{ opacity: 0, scale: 0.9 }}
                        whileInView={{ opacity: 1, scale: 1 }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.5, delay: index * 0.05 }}
                        className="break-inside-avoid"
                      >
                        <motion.div whileHover={{ y: -5 }}>
                          <Card
                            className="overflow-hidden cursor-pointer group relative border-2 border-transparent hover:border-navy/20 transition-all duration-500 hover:shadow-2xl"
                            onClick={() => setSelectedImage(image)}
                            data-testid={`card-gallery-${image.id}`}
                          >
                            <div className="relative overflow-hidden">
                              <motion.img
                                src={image.imageUrl}
                                alt={image.title}
                                className="w-full h-auto object-cover"
                                whileHover={{ scale: 1.1 }}
                                transition={{ duration: 0.6 }}
                              />
                              <motion.div 
                                className="absolute inset-0 bg-gradient-to-t from-navy/90 via-navy/40 to-transparent"
                                initial={{ opacity: 0 }}
                                whileHover={{ opacity: 1 }}
                                transition={{ duration: 0.3 }}
                              >
                                <div className="absolute bottom-0 left-0 right-0 p-6">
                                  <h3 className="font-heading font-bold text-cream text-lg mb-2">{image.title}</h3>
                                  {image.description && (
                                    <p className="text-sm text-cream/80">{image.description}</p>
                                  )}
                                </div>
                              </motion.div>
                              <motion.div 
                                className="absolute top-4 right-4"
                                initial={{ opacity: 0, scale: 0.8 }}
                                whileHover={{ opacity: 1, scale: 1 }}
                              >
                                <div className="p-3 bg-navy/20 backdrop-blur-md rounded-full">
                                  <ZoomIn className="h-5 w-5 text-cream" />
                                </div>
                              </motion.div>
                            </div>
                          </Card>
                        </motion.div>
                      </motion.div>
                    ))}
              </div>
            </TabsContent>

            <TabsContent value="videos" className="mt-12">
              <StaggerContainer className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {videosLoading
                  ? [...Array(6)].map((_, i) => (
                      <Card key={i} className="overflow-hidden">
                        <Skeleton className="w-full aspect-video" />
                        <div className="p-6 space-y-3">
                          <Skeleton className="h-6 w-3/4" />
                          <Skeleton className="h-16 w-full" />
                        </div>
                      </Card>
                    ))
                  : videos?.map((video, index) => {
                      const videoId = extractYouTubeId(video.youtubeUrl);
                      return (
                        <StaggerItem key={video.id}>
                          <motion.div
                            whileHover={{ y: -10 }}
                            transition={{ type: "spring", stiffness: 300 }}
                          >
                            <Card className="overflow-hidden h-full flex flex-col border-2 border-navy/5 hover:border-navy/20 hover:shadow-2xl transition-all duration-500 group" data-testid={`card-video-${video.id}`}>
                              <div className="relative aspect-video bg-gradient-to-br from-navy/10 to-solar/10 group-hover:from-navy/20 group-hover:to-solar/20 transition-all">
                                {videoId ? (
                                  <iframe
                                    src={`https://www.youtube.com/embed/${videoId}`}
                                    title={video.title}
                                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                    allowFullScreen
                                    className="w-full h-full"
                                  />
                                ) : video.thumbnail ? (
                                  <img
                                    src={video.thumbnail}
                                    alt={video.title}
                                    className="w-full h-full object-cover"
                                  />
                                ) : (
                                  <div className="w-full h-full flex items-center justify-center">
                                    <motion.div
                                      animate={{ scale: [1, 1.2, 1] }}
                                      transition={{ duration: 2, repeat: Infinity }}
                                    >
                                      <Play className="h-16 w-16 text-navy/30" />
                                    </motion.div>
                                  </div>
                                )}
                              </div>
                              <div className="p-6 flex-1">
                                <h3 className="text-xl font-heading font-bold mb-3" data-testid={`text-video-title-${video.id}`}>
                                  {video.title}
                                </h3>
                                {video.description && (
                                  <p className="text-muted-foreground">{video.description}</p>
                                )}
                              </div>
                            </Card>
                          </motion.div>
                        </StaggerItem>
                      );
                    })}
              </StaggerContainer>
            </TabsContent>
          </Tabs>
        </div>
      </section>

      <AnimatePresence>
        {selectedImage && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setSelectedImage(null)}
            className="fixed inset-0 bg-navy/95 backdrop-blur-xl z-50 flex items-center justify-center p-4"
            data-testid="modal-gallery-lightbox"
          >
            <motion.div
              initial={{ scale: 0.8, opacity: 0, y: 50 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.8, opacity: 0, y: 50 }}
              transition={{ type: "spring", stiffness: 300, damping: 30 }}
              onClick={(e) => e.stopPropagation()}
              className="relative max-w-6xl w-full"
            >
              <motion.div whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.95 }}>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => setSelectedImage(null)}
                  className="absolute -top-14 right-0 text-cream hover:text-cream/80 hover:bg-cream/10 rounded-full"
                  data-testid="button-close-lightbox"
                >
                  <X className="h-8 w-8" />
                </Button>
              </motion.div>
              <motion.img
                src={selectedImage.imageUrl}
                alt={selectedImage.title}
                className="w-full h-auto max-h-[80vh] object-contain rounded-2xl shadow-2xl"
                layoutId={`image-${selectedImage.id}`}
              />
              <motion.div 
                className="mt-6 text-center text-cream"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
              >
                <h3 className="text-2xl font-heading font-bold mb-2">{selectedImage.title}</h3>
                {selectedImage.description && (
                  <p className="text-cream/70 text-lg">{selectedImage.description}</p>
                )}
              </motion.div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

