      }
      return apiRequest("POST", "/api/videos", data);
    },
    onSuccess: () => {
      toast({
        title: "Saved!",
        description: `Video has been ${video ? "updated" : "added"} successfully.`,
      });
      queryClient.invalidateQueries({ queryKey: ["/api/videos"] });
