                    control={form.control}
                    name="heroSubtitle"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Hero Subtitle</FormLabel>
                        <FormControl>
                          <Input
                            {...field}
                            placeholder="Empowering Young Minds to Explore, Discover & Transform"
                            data-testid="input-hero-subtitle"
