                    <p className="text-2xl font-heading font-bold text-aurora">{stat.value}+</p>
                    <p className="text-xs text-muted-foreground">{stat.label}</p>
                  </motion.div>
                ))}
              </div>
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
}

